  IF v_active <> 0 THEN RAISE EXCEPTION 'an OSM row is not staged (%)', v_active; END IF;
  IF v_staged < 399 THEN RAISE EXCEPTION 'expected at least 399 staged OSM rows, found %', v_staged; END IF;
